@Test
public void testSubstitute() {
    String timeFormat = "yyyyMMddHHmmss";
    DateTimeFormatter df = DateTimeFormatter.ofPattern(timeFormat);
    String formattedDate = df.format(ZonedDateTime.now());
    String path = "data_${now}_${uuid}.parquet";
    String newPath = VariablesSubstitute.substitute(path, timeFormat);
    Assert.assertTrue(newPath.contains(formattedDate));
    String text = "${var1} is a distributed, high-performance data integration platform for " + "the synchronization and ${var2} of massive data (offline & real-time).";
    HashMap<String, String> valuesMap = new HashMap<>();
    valuesMap.put("var1", "SeaTunnel");
    valuesMap.put("var2", "transformation");
    String newText = VariablesSubstitute.substitute(text, valuesMap);
    Assert.assertTrue(newText.contains("SeaTunnel") && newText.contains("transformation"));
}

@Test
public void testVariables() throws URISyntaxException {
    // We use a map to mock the system property, since the system property will be only loaded once
    // after the test is run. see Issue #1670
    Map<String, String> systemProperties = new HashMap<>();
    systemProperties.put("dt", "20190318");
    systemProperties.put("city2", "shanghai");
    Config config = ConfigFactory.parseFile(FileUtils.getFileFromResources("/seatunnel/variables.conf")).resolveWith(ConfigFactory.parseMap(systemProperties), ConfigResolveOptions.defaults().setAllowUnresolved(true));
    String sql1 = config.getConfigList("transform").get(1).getString("sql");
    String sql2 = config.getConfigList("transform").get(2).getString("sql");
    Assert.assertTrue(sql1.contains("shanghai"));
    Assert.assertTrue(sql2.contains("20190318"));
}

